import React, { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom'; // React Router hooks
import { fetchItemById } from './api'; // Ensure the correct import for the API function

const PlaceDetails = () => {
    const { id } = useParams(); // Extract id from URL params
    const navigate = useNavigate(); // To navigate programmatically

    const [place, setPlace] = useState(null); // State to store place data
    const [loading, setLoading] = useState(true); // State to track loading state
    const [error, setError] = useState(null); // State to track error

    useEffect(() => {
        // This function will fetch the place by ID
        const fetchPlace = async () => {
            setLoading(true); // Start loading
            try {
                const data = await fetchItemById(id); // Fetch place data by ID
                setPlace(data); // Set the place data
                setError(null); // Reset any errors
            } catch (error) {
                setError('Item not found or an error occurred while fetching data.'); // Handle error
                console.error('Error fetching item:', error);
            } finally {
                setLoading(false); // Stop loading
            }
        };

        fetchPlace(); // Call the fetch function when the component mounts or id changes
    }, [id]); // Re-run the effect when `id` changes

    // Display loading state
    if (loading) {
        return <div>Loading...</div>;
    }

    // Display error message
    if (error) {
        return <div>{error}</div>;
    }

    // Display place details if available
    if (place) {
        return (
            <div className="place-details">
                <img src={place.image} alt={place.location} className="place-details-img" />
                <div className="place-hero">
                    <h2>{place.name}</h2>
                    <p><strong>About: </strong> {place.description}</p>
                    <p><strong>Max Visitors: </strong> {place.maxVisitors}</p>
                    <p><strong>Location: </strong> {place.location}</p>
                    <p className="price">Price: {place.price} UAH/day</p>
                    <div className="buttons">
                        <button onClick={() => navigate('/catalog')}>Return to catalog</button>
                        <button>Add to cart</button>
                    </div>
                </div>
            </div>
        );
    }

    return null; // Return null if place data is not available (shouldn't happen if the `id` is valid)
};

export default PlaceDetails;
